{
  "name": "MoveGuru",
  "description": "Defense-Grade Logistics Thin Client. Uses Gemini Live API to digitize household inventories via real-time video streaming.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface InventoryItem {
  id: string;
  name: string;
  weight: number;
  status: 'KEEP' | 'DONATE' | 'TRASH';
  condition: string;
  timestamp: number;
  tariffCredit: number;
  carbonSaved: number;
}

export interface Badge {
  id: string;
  name: string;
  xp: number;
  timestamp: number;
  icon?: string;
}

export interface WasteMetrics {
  totalWeight: number;
  totalCarbonSaved: number;
  totalTariffCredit: number;
  inventoryCount: number;
}

/**
 * WasteDiversionLogic.ts
 * "Defense-Grade" calculations for logistics optimization.
 */

// Hypothetical tariff savings per lb based on GHC contract data
const TARIFF_RATE_PER_LB = 2.15; 

// EPA estimates: ~0.82 lbs of CO2e per lb of furniture diverted from landfill
const CARBON_FACTOR = 0.82; 

interface EstimationResult {
  estimatedWeight: number;
  tariffCredit: number;
  carbonSaved: number;
}

const AVERAGE_WEIGHTS: Record<string, number> = {
  'sofa': 150,
  'couch': 150,
  'chair': 40,
  'table': 60,
  'bed': 180,
  'mattress': 70,
  'tv': 30,
  'television': 30,
  'shelf': 45,
  'bookshelf': 50,
  'dresser': 100,
  'cabinet': 80,
  'lamp': 10,
  'box': 25,
  'rug': 20,
};

export function calculateDiversionMetrics(itemName: string, providedWeight?: number, status?: string): EstimationResult {
  const normalizedName = itemName.toLowerCase();

  // 1. Determine Weight
  // If AI provides a weight, use it. Otherwise, estimate based on heuristics.
  let weight = providedWeight;

  if (!weight || weight === 0) {
    // Simple partial match lookup
    const foundKey = Object.keys(AVERAGE_WEIGHTS).find(key => normalizedName.includes(key));
    weight = foundKey ? AVERAGE_WEIGHTS[foundKey] : 20; // Default fallback 20lbs
  }

  // 2. Calculate Credits
  // Only apply credits if the item is NOT being shipped (i.e., DONATE or TRASH)
  // For this prototype, we emphasize 'DONATE' for circular economy credits.
  const isDiverted = status === 'DONATE';

  const tariffCredit = isDiverted ? (weight * TARIFF_RATE_PER_LB) : 0;
  const carbonSaved = isDiverted ? (weight * CARBON_FACTOR) : 0;

  return {
    estimatedWeight: weight,
    tariffCredit: Number(tariffCredit.toFixed(2)),
    carbonSaved: Number(carbonSaved.toFixed(2)),
  };
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { 
  GoogleGenAI, 
  LiveServerMessage, 
  Modality, 
  FunctionDeclaration, 
  Type, 
  Blob 
} from '@google/genai';
import { InventoryItem, Badge } from '../types';
import { calculateDiversionMetrics } from '../services/wasteDiversionLogic';

// --- Types & Config ---

interface UseGeminiLiveProps {
  videoRef: React.RefObject<HTMLVideoElement>;
  onItemLogged: (item: InventoryItem) => void;
  onBadgeAwarded: (badge: Badge) => void;
}

const MODEL_NAME = 'gemini-2.5-flash-native-audio-preview-09-2025';

// --- Helper: Audio Encoding/Decoding ---

function createBlob(data: Float32Array): Blob {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) {
    int16[i] = data[i] * 32768;
  }

  // Convert Int16Array to a binary string manually for btoa
  let binary = '';
  const bytes = new Uint8Array(int16.buffer);
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }

  return {
    data: btoa(binary),
    mimeType: 'audio/pcm;rate=16000',
  };
}

function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

async function blobToBase64(blob: globalThis.Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
}

// --- Tools Declarations ---

const logItemTool: FunctionDeclaration = {
  name: 'log_item',
  description: 'Log a household item into the inventory database.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      name: { type: Type.STRING, description: 'The name of the item (e.g. Sofa, TV).' },
      weight: { type: Type.NUMBER, description: 'Estimated weight in lbs.' },
      status: { type: Type.STRING, description: 'One of: KEEP, DONATE, TRASH', enum: ['KEEP', 'DONATE', 'TRASH'] },
      condition: { type: Type.STRING, description: 'Brief description of condition (e.g. Scratched, New).' },
    },
    required: ['name', 'status'],
  },
};

const awardBadgeTool: FunctionDeclaration = {
  name: 'award_badge',
  description: 'Award gamification XP to the user.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      badgeName: { type: Type.STRING, description: 'Name of the badge (e.g. Eco Warrior).' },
      xp: { type: Type.NUMBER, description: 'XP amount.' },
    },
    required: ['badgeName', 'xp'],
  },
};

// --- The Hook ---

export function useGeminiLive({ videoRef, onItemLogged, onBadgeAwarded }: UseGeminiLiveProps) {
  const [isStreaming, setIsStreaming] = useState(false);
  const [isConnected, setIsConnected] = useState(false);
  const [volume, setVolume] = useState(0); // For mic visualizer

  // Refs for audio handling to avoid re-renders
  const audioContextRef = useRef<AudioContext | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Stream Ref
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const videoIntervalRef = useRef<number | null>(null);

  const startStream = useCallback(async () => {
    if (!process.env.API_KEY) {
      console.error("No API Key found");
      return;
    }

    try {
      setIsStreaming(true);

      // 1. Initialize Audio Contexts
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      const inputCtx = new AudioContextClass({ sampleRate: 16000 });
      const outputCtx = new AudioContextClass({ sampleRate: 24000 }); // Model outputs 24kHz

      inputAudioContextRef.current = inputCtx;
      audioContextRef.current = outputCtx;
      nextStartTimeRef.current = 0;

      // 2. Setup Mic Stream
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const source = inputCtx.createMediaStreamSource(stream);
      const analyzer = inputCtx.createAnalyser(); // For visualizer
      analyzer.fftSize = 256;

      // ScriptProcessor for raw PCM access (legacy but robust for this API pattern)
      const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);

      scriptProcessor.onaudioprocess = (e) => {
        if (!sessionPromiseRef.current) return;

        const inputData = e.inputBuffer.getChannelData(0);

        // Simple volume meter
        let sum = 0;
        for(let i=0; i<inputData.length; i++) sum += inputData[i] * inputData[i];
        setVolume(Math.sqrt(sum / inputData.length));

        const pcmBlob = createBlob(inputData);
        sessionPromiseRef.current.then(session => {
            session.sendRealtimeInput({ media: pcmBlob });
        });
      };

      source.connect(analyzer);
      source.connect(scriptProcessor);
      scriptProcessor.connect(inputCtx.destination);

      // 3. Connect to Gemini Live
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const sessionPromise = ai.live.connect({
        model: MODEL_NAME,
        config: {
          responseModalities: [Modality.AUDIO],
          tools: [{ functionDeclarations: [logItemTool, awardBadgeTool] }],
          systemInstruction: `You are the MoveGuru Logistics Officer. You are watching a live video stream of a user's home.
YOUR GOALS:
1. Identify & Log: When you see a distinct item (e.g., Sofa, TV), identify it using Harmonized System (HS) Codes (Chapter 94) logic.
2. Verify Condition: Ask the user specific questions about damage. ('I see a scratch on that leg. Is that pre-existing?')
3. Waste Diversion: If an item looks heavy/low-value (e.g., particle board shelf), suggest donating it. ('That weighs ~50lbs. Donating it would save the Govt $100 in tariffs. Want to tag it for the Base Exchange?')
4. Gamify: When a user confirms an item, excitedly announce '+50 Inventory XP' and trigger the award_badge tool.

OUTPUT:
Audio: Speak to the user like a helpful, efficient mover. Short, crisp sentences.
Tool Calls: Call log_item({ name, weight, status }) silently in the background when an item is confirmed.`,
        },
        callbacks: {
          onopen: () => {
            console.log("Gemini Live Connected");
            setIsConnected(true);
          },
          onmessage: async (message: LiveServerMessage) => {
             // Handle Audio Output
             const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
             if (audioData) {
               if (outputCtx.state === 'suspended') await outputCtx.resume();

               const decoded = decode(audioData);
               const audioBuffer = await decodeAudioData(decoded, outputCtx, 24000, 1);

               const node = outputCtx.createBufferSource();
               node.buffer = audioBuffer;
               node.connect(outputCtx.destination);

               // Schedule
               const currentTime = outputCtx.currentTime;
               // Ensure we don't schedule in the past
               const startTime = Math.max(currentTime, nextStartTimeRef.current);
               node.start(startTime);
               nextStartTimeRef.current = startTime + audioBuffer.duration;

               sourcesRef.current.add(node);
               node.onended = () => sourcesRef.current.delete(node);
             }

             // Handle Tool Calls
             if (message.toolCall) {
                console.log("Tool Call Received:", message.toolCall);
                const responses = [];

                for (const fc of message.toolCall.functionCalls) {
                    let result = { result: 'ok' };

                    if (fc.name === 'log_item') {
                        const { name, weight, status, condition } = fc.args as any;

                        // Calculate metrics locally
                        const metrics = calculateDiversionMetrics(name, weight, status);

                        const newItem: InventoryItem = {
                            id: crypto.randomUUID(),
                            name,
                            weight: metrics.estimatedWeight,
                            status: (status as any) || 'KEEP',
                            condition: condition || 'Good',
                            timestamp: Date.now(),
                            tariffCredit: metrics.tariffCredit,
                            carbonSaved: metrics.carbonSaved
                        };

                        onItemLogged(newItem);
                        result = { result: `Item ${name} logged successfully.` };
                    } else if (fc.name === 'award_badge') {
                        const { badgeName, xp } = fc.args as any;
                        const newBadge: Badge = {
                            id: crypto.randomUUID(),
                            name: badgeName,
                            xp,
                            timestamp: Date.now()
                        };
                        onBadgeAwarded(newBadge);
                        result = { result: `Badge ${badgeName} awarded.` };
                    }

                    responses.push({
                        id: fc.id,
                        name: fc.name,
                        response: result
                    });
                }

                // Send Tool Response back to model
                sessionPromise.then(session => {
                    session.sendToolResponse({ functionResponses: responses });
                });
             }
          },
          onclose: () => {
            console.log("Gemini Live Closed");
            setIsConnected(false);
          },
          onerror: (err) => {
            console.error("Gemini Live Error", err);
            setIsConnected(false);
          }
        }
      });

      sessionPromiseRef.current = sessionPromise;

      // 4. Start Video Stream (2 FPS)
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');

      const intervalId = window.setInterval(async () => {
        if (!videoRef.current || !sessionPromiseRef.current) return;

        const video = videoRef.current;
        if (video.videoWidth === 0) return;

        // Downscale for performance/tokens - 640px width is usually sufficient
        const scale = 0.5;
        canvas.width = video.videoWidth * scale;
        canvas.height = video.videoHeight * scale;

        ctx?.drawImage(video, 0, 0, canvas.width, canvas.height);

        canvas.toBlob(async (blob) => {
            if (!blob) return;
            const base64 = await blobToBase64(blob);
            sessionPromiseRef.current?.then(session => {
                session.sendRealtimeInput({
                    media: {
                        mimeType: 'image/jpeg',
                        data: base64
                    }
                });
            });
        }, 'image/jpeg', 0.6); // 60% quality JPEG

      }, 500); // 500ms = 2 FPS

      videoIntervalRef.current = intervalId;

    } catch (e) {
      console.error("Failed to start stream", e);
      setIsStreaming(false);
    }
  }, [videoRef, onItemLogged, onBadgeAwarded]);

  const stopStream = useCallback(() => {
    if (sessionPromiseRef.current) {
        sessionPromiseRef.current.then(session => session.close());
        sessionPromiseRef.current = null;
    }

    if (videoIntervalRef.current) {
        clearInterval(videoIntervalRef.current);
        videoIntervalRef.current = null;
    }

    if (inputAudioContextRef.current) {
        inputAudioContextRef.current.close();
        inputAudioContextRef.current = null;
    }

    if (audioContextRef.current) {
        audioContextRef.current.close();
        audioContextRef.current = null;
    }

    setIsStreaming(false);
    setIsConnected(false);
    setVolume(0);
  }, []);

  return {
    isStreaming,
    isConnected,
    volume,
    startStream,
    stopStream
  };
}

import React, { useEffect, useState } from 'react';
import { InventoryItem, Badge, WasteMetrics } from '../types';

interface InventoryOverlayProps {
  items: InventoryItem[];
  badges: Badge[];
  metrics: WasteMetrics;
  isStreaming: boolean;
  isConnected: boolean;
  volume: number;
  onToggleStream: () => void;
}

export const InventoryOverlay: React.FC<InventoryOverlayProps> = ({
  items,
  badges,
  metrics,
  isStreaming,
  isConnected,
  volume,
  onToggleStream
}) => {
  const [latestBadge, setLatestBadge] = useState<Badge | null>(null);

  useEffect(() => {
    if (badges.length > 0) {
      setLatestBadge(badges[badges.length - 1]);
      const timer = setTimeout(() => setLatestBadge(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [badges]);

  // Reverse items to show newest first
  const recentItems = [...items].reverse().slice(0, 3);

  return (
    <div className="absolute inset-0 pointer-events-none flex flex-col justify-between z-10 p-4 safe-area-inset">

      {/* Top HUD: Status & Metrics */}
      <div className="flex justify-between items-start">
        <div className="bg-black/60 backdrop-blur-md rounded-lg p-3 border-l-4 border-green-500">
          <div className="text-xs text-gray-400 uppercase tracking-widest font-bold">Carbon Saved</div>
          <div className="text-xl font-mono text-green-400">{metrics.totalCarbonSaved.toFixed(1)} lbs</div>

          <div className="mt-2 text-xs text-gray-400 uppercase tracking-widest font-bold">Tariff Credit</div>
          <div className="text-xl font-mono text-blue-400">${metrics.totalTariffCredit.toFixed(2)}</div>
        </div>

        <div className="flex flex-col items-end gap-2">
           <div className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-widest flex items-center gap-2 ${isConnected ? 'bg-green-500/20 text-green-400 border border-green-500/50' : 'bg-red-500/20 text-red-400 border border-red-500/50'}`}>
              <div className={`w-2 h-2 rounded-full ${isConnected ? 'bg-green-500 animate-pulse' : 'bg-red-500'}`} />
              {isConnected ? 'LIVE UPLINK' : 'OFFLINE'}
           </div>

           {/* XP Badge Count */}
           <div className="bg-purple-900/80 rounded-lg p-2 border border-purple-500/50 text-right">
             <div className="text-xs text-purple-200">Total XP</div>
             <div className="text-lg font-bold text-white">{badges.reduce((acc, b) => acc + b.xp, 0)}</div>
           </div>
        </div>
      </div>

      {/* Center: Badge Notifications */}
      <div className="flex justify-center items-center flex-grow">
        {latestBadge && (
           <div className="bg-gradient-to-r from-purple-900 to-indigo-900 border-2 border-yellow-400 rounded-xl p-6 shadow-[0_0_50px_rgba(168,85,247,0.5)] transform animate-bounce flex flex-col items-center">
              <div className="text-4xl mb-2">🏅</div>
              <div className="text-2xl font-bold text-white uppercase tracking-wider">{latestBadge.name}</div>
              <div className="text-yellow-300 font-mono text-xl">+{latestBadge.xp} XP</div>
           </div>
        )}
      </div>

      {/* Bottom HUD: Inventory Stream & Controls */}
      <div className="flex flex-col gap-4">

        {/* Recent Items Stream */}
        <div className="space-y-2 pointer-events-auto max-h-48 overflow-y-auto">
          {recentItems.map(item => (
            <div key={item.id} className="bg-black/70 backdrop-blur-md rounded-lg p-3 border-l-4 border-blue-500 flex justify-between items-center transform transition-all hover:scale-105">
              <div>
                <div className="font-bold text-white text-sm">{item.name}</div>
                <div className="text-xs text-gray-400">{item.condition} • {item.weight}lbs</div>
              </div>
              <div className={`text-xs font-bold px-2 py-1 rounded ${item.status === 'DONATE' ? 'bg-green-500/20 text-green-400' : 'bg-blue-500/20 text-blue-400'}`}>
                {item.status}
              </div>
            </div>
          ))}
        </div>

        {/* Controls */}
        <div className="flex justify-center items-center pb-8 pt-4 pointer-events-auto">
          <button 
            onClick={onToggleStream}
            className={`relative group rounded-full w-20 h-20 flex items-center justify-center transition-all ${isStreaming ? 'bg-red-500/20 hover:bg-red-500/40' : 'bg-white/10 hover:bg-white/20'}`}
          >
            {/* Visualizer Ring */}
            {isStreaming && (
              <div 
                className="absolute inset-0 rounded-full border-2 border-green-500 opacity-50"
                style={{ transform: `scale(${1 + volume * 2})` }}
              />
            )}

            <div className={`z-10 w-16 h-16 rounded-full flex items-center justify-center transition-colors ${isStreaming ? 'bg-red-500' : 'bg-green-500 shadow-[0_0_20px_rgba(34,197,94,0.5)]'}`}>
              {isStreaming ? (
                <div className="w-6 h-6 bg-white rounded-sm" />
              ) : (
                <svg className="w-8 h-8 text-white ml-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
              )}
            </div>
          </button>
        </div>
      </div>

    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { InventoryItem, Badge, WasteMetrics } from './types';
import { useGeminiLive } from './hooks/useGeminiLive';
import { InventoryOverlay } from './components/InventoryOverlay';

export default function App() {
  const videoRef = useRef<HTMLVideoElement>(null);

  // App State
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [badges, setBadges] = useState<Badge[]>([]);

  // Derived Metrics
  const metrics: WasteMetrics = {
    totalWeight: inventory.reduce((acc, item) => acc + item.weight, 0),
    totalCarbonSaved: inventory.reduce((acc, item) => acc + item.carbonSaved, 0),
    totalTariffCredit: inventory.reduce((acc, item) => acc + item.tariffCredit, 0),
    inventoryCount: inventory.length
  };

  const handleItemLogged = (item: InventoryItem) => {
    setInventory(prev => [...prev, item]);
  };

  const handleBadgeAwarded = (badge: Badge) => {
    setBadges(prev => [...prev, badge]);
  };

  const { isStreaming, isConnected, volume, startStream, stopStream } = useGeminiLive({
    videoRef,
    onItemLogged: handleItemLogged,
    onBadgeAwarded: handleBadgeAwarded
  });

  // Setup Video Stream locally for the user to see
  useEffect(() => {
    async function setupCamera() {
      if (videoRef.current) {
        try {
          const stream = await navigator.mediaDevices.getUserMedia({ 
            video: { 
              facingMode: 'environment', // Rear camera preferred
              width: { ideal: 1280 },
              height: { ideal: 720 }
            } 
          });
          videoRef.current.srcObject = stream;
        } catch (err) {
          console.error("Camera access denied", err);
        }
      }
    }
    setupCamera();
  }, []);

  const toggleStream = () => {
    if (isStreaming) {
      stopStream();
    } else {
      startStream();
    }
  };

  return (
    <div className="relative w-screen h-screen bg-black overflow-hidden">
      {/* 1. Camera View */}
      <video 
        ref={videoRef}
        autoPlay 
        playsInline 
        muted 
        className="absolute inset-0 w-full h-full object-cover opacity-80"
      />

      {/* 2. Grid Overlay (Scanning Aesthetic) */}
      <div className="absolute inset-0 pointer-events-none" style={{
        backgroundImage: 'linear-gradient(rgba(0, 255, 0, 0.03) 1px, transparent 1px), linear-gradient(90deg, rgba(0, 255, 0, 0.03) 1px, transparent 1px)',
        backgroundSize: '40px 40px'
      }} />

      {/* 3. Vignette */}
      <div className="absolute inset-0 pointer-events-none bg-[radial-gradient(circle_at_center,transparent_0%,rgba(0,0,0,0.6)_100%)]" />

      {/* 4. UI Layer */}
      <InventoryOverlay 
        items={inventory}
        badges={badges}
        metrics={metrics}
        isStreaming={isStreaming}
        isConnected={isConnected}
        volume={volume}
        onToggleStream={toggleStream}
      />
    </div>
  );
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  GoogleGenAI, 
  LiveServerMessage, 
  Modality, 
  FunctionDeclaration, 
  Type, 
  Blob 
} from '@google/genai';
import { InventoryItem, Badge } from '../types';
import { calculateDiversionMetrics } from '../services/wasteDiversionLogic';

// --- Types & Config ---

interface UseGeminiLiveProps {
  videoRef: React.RefObject<HTMLVideoElement>;
  onItemLogged: (item: InventoryItem) => void;
  onBadgeAwarded: (badge: Badge) => void;
}

const MODEL_NAME = 'gemini-2.5-flash-native-audio-preview-09-2025';

// --- Helper: Audio Encoding/Decoding ---

function createBlob(data: Float32Array): Blob {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) {
    int16[i] = data[i] * 32768;
  }

  // Convert Int16Array to a binary string manually for btoa
  let binary = '';
  const bytes = new Uint8Array(int16.buffer);
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }

  return {
    data: btoa(binary),
    mimeType: 'audio/pcm;rate=16000',
  };
}

function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
