      weight: { type: Type.NUMBER, description: 'Estimated weight in lbs.' },
      status: { type: Type.STRING, description: 'One of: KEEP, DONATE, TRASH', enum: ['KEEP', 'DONATE', 'TRASH'] },
      condition: { type: Type.STRING, description: 'Brief description of condition (e.g. Scratched, New).' },
    },
    required: ['name', 'status'],
  },
};

const awardBadgeTool: FunctionDeclaration = {
  name: 'award_badge',
  description: 'Award gamification XP to the user.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      badgeName: { type: Type.STRING, description: 'Name of the badge (e.g. Eco Warrior).' },
      xp: { type: Type.NUMBER, description: 'XP amount.' },
    },
    required: ['badgeName', 'xp'],
  },
};

// --- The Hook ---

export function useGeminiLive({ videoRef, onItemLogged, onBadgeAwarded }: UseGeminiLiveProps) {
  const [isStreaming, setIsStreaming] = useState(false);
  const [isConnected, setIsConnected] = useState(false);
  const [volume, setVolume] = useState(0); 
  const [transcript, setTranscript] = useState<{role: 'user' | 'model', text: string} | null>(null);

  // Refs for audio handling to avoid re-renders
  const audioContextRef = useRef<AudioContext | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Stream Ref
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const videoIntervalRef = useRef<number | null>(null);

  const startStream = useCallback(async () => {
    if (!process.env.API_KEY) {
      console.error("No API Key found");
      return;
    }

    try {
      setIsStreaming(true);

      // 1. Initialize Audio Contexts
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      const inputCtx = new AudioContextClass({ sampleRate: 16000 });
      const outputCtx = new AudioContextClass({ sampleRate: 24000 }); // Model outputs 24kHz

      inputAudioContextRef.current = inputCtx;
      audioContextRef.current = outputCtx;
      nextStartTimeRef.current = 0;

      // 2. Setup Mic Stream
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const source = inputCtx.createMediaStreamSource(stream);
      const analyzer = inputCtx.createAnalyser(); // For visualizer
      analyzer.fftSize = 256;

      const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);

      scriptProcessor.onaudioprocess = (e) => {
        if (!sessionPromiseRef.current) return;

        const inputData = e.inputBuffer.getChannelData(0);

        // Simple volume meter
        let sum = 0;
        for(let i=0; i<inputData.length; i++) sum += inputData[i] * inputData[i];
        setVolume(Math.sqrt(sum / inputData.length));

        const pcmBlob = createBlob(inputData);
        sessionPromiseRef.current.then(session => {
            session.sendRealtimeInput({ media: pcmBlob });
        });
      };

      source.connect(analyzer);
      source.connect(scriptProcessor);
      scriptProcessor.connect(inputCtx.destination);

      // 3. Connect to Gemini Live
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const sessionPromise = ai.live.connect({
        model: MODEL_NAME,
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          // Enable transcription to display captions
          inputAudioTranscription: { model: 'google-default' },
          outputAudioTranscription: { model: 'google-default' },
          tools: [{ functionDeclarations: [logItemTool, awardBadgeTool] }],
          systemInstruction: {
            parts: [{
              text: `You are the MoveGuru Logistics Officer. You are watching a live video stream of a user's home.
YOUR GOALS:
1. Identify & Log: When you see a distinct item (e.g., Sofa, TV), identify it using Harmonized System (HS) Codes (Chapter 94) logic.
2. Verify Condition: Ask the user specific questions about damage. ('I see a scratch on that leg. Is that pre-existing?')
3. Waste Diversion: If an item looks heavy/low-value (e.g., particle board shelf), suggest donating it. ('That weighs ~50lbs. Donating it would save the Govt $100 in tariffs. Want to tag it for the Base Exchange?')
4. Gamify: When a user confirms an item, excitedly announce '+50 Inventory XP' and trigger the award_badge tool.

OUTPUT:
Audio: Speak to the user like a helpful, efficient mover. Short, crisp sentences.
Tool Calls: Call log_item({ name, weight, status }) silently in the background when an item is confirmed.`
            }]
          },
        },
        callbacks: {
          onopen: () => {
            console.log("Gemini Live Connected");
            setIsConnected(true);
          },
          onmessage: async (message: LiveServerMessage) => {
             // Handle Transcriptions
             const serverContent = message.serverContent;
             if (serverContent?.modelTurn?.parts?.[0]?.text) {
                 // Sometimes text comes in modelTurn (rare with audio modality but possible)
             }

             if (serverContent?.outputTranscription?.text) {
                 setTranscript({ role: 'model', text: serverContent.outputTranscription.text });
             } else if (serverContent?.inputTranscription?.text) {
                 setTranscript({ role: 'user', text: serverContent.inputTranscription.text });
             }

             // Handle Audio Output
             const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
             if (audioData) {
               if (outputCtx.state === 'suspended') await outputCtx.resume();

               const decoded = decode(audioData);
               const audioBuffer = await decodeAudioData(decoded, outputCtx, 24000, 1);

               const node = outputCtx.createBufferSource();
               node.buffer = audioBuffer;
               node.connect(outputCtx.destination);

               const currentTime = outputCtx.currentTime;
               const startTime = Math.max(currentTime, nextStartTimeRef.current);
               node.start(startTime);
               nextStartTimeRef.current = startTime + audioBuffer.duration;

               sourcesRef.current.add(node);
               node.onended = () => sourcesRef.current.delete(node);
             }

             // Handle Tool Calls
             if (message.toolCall) {
                console.log("Tool Call Received:", message.toolCall);
                const responses = [];

                for (const fc of message.toolCall.functionCalls) {
                    let result = { result: 'ok' };

                    if (fc.name === 'log_item') {
                        const { name, weight, status, condition } = fc.args as any;
                        const metrics = calculateDiversionMetrics(name, weight, status);
                        const newItem: InventoryItem = {
                            id: crypto.randomUUID(),
                            name,
                            weight: metrics.estimatedWeight,
                            status: (status as any) || 'KEEP',
                            condition: condition || 'Good',
                            timestamp: Date.now(),
                            tariffCredit: metrics.tariffCredit,
                            carbonSaved: metrics.carbonSaved
                        };
                        onItemLogged(newItem);
                        result = { result: `Item ${name} logged successfully.` };
                    } else if (fc.name === 'award_badge') {
                        const { badgeName, xp } = fc.args as any;
                        const newBadge: Badge = {
                            id: crypto.randomUUID(),
                            name: badgeName,
                            xp,
                            timestamp: Date.now()
                        };
                        onBadgeAwarded(newBadge);
                        result = { result: `Badge ${badgeName} awarded.` };
                    }

                    responses.push({
                        id: fc.id,
                        name: fc.name,
                        response: result
                    });
                }

                sessionPromise.then(session => {
                    session.sendToolResponse({ functionResponses: responses });
                });
             }
          },
          onclose: () => {
            console.log("Gemini Live Closed");
            setIsConnected(false);
          },
          onerror: (err) => {
            console.error("Gemini Live Error", err);
            setIsConnected(false);
          }
        }
      });

      sessionPromiseRef.current = sessionPromise;

      // 4. Start Video Stream (2 FPS)
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');

      const intervalId = window.setInterval(async () => {
        if (!videoRef.current || !sessionPromiseRef.current) return;
        const video = videoRef.current;
        if (video.videoWidth === 0) return;

        const scale = 0.5;
        canvas.width = video.videoWidth * scale;
        canvas.height = video.videoHeight * scale;

        ctx?.drawImage(video, 0, 0, canvas.width, canvas.height);

        canvas.toBlob(async (blob) => {
            if (!blob) return;
            const base64 = await blobToBase64(blob);
            sessionPromiseRef.current?.then(session => {
                session.sendRealtimeInput({
                    media: {
                        mimeType: 'image/jpeg',
                        data: base64
                    }
                });
            });
        }, 'image/jpeg', 0.6);

      }, 500);

      videoIntervalRef.current = intervalId;

    } catch (e) {
      console.error("Failed to start stream", e);
      setIsStreaming(false);
    }
  }, [videoRef, onItemLogged, onBadgeAwarded]);

  const stopStream = useCallback(() => {
    if (sessionPromiseRef.current) {
        sessionPromiseRef.current.then(session => session.close());
        sessionPromiseRef.current = null;
    }

    if (videoIntervalRef.current) {
        clearInterval(videoIntervalRef.current);
        videoIntervalRef.current = null;
    }

    if (inputAudioContextRef.current) {
        inputAudioContextRef.current.close();
        inputAudioContextRef.current = null;
    }

    if (audioContextRef.current) {
        audioContextRef.current.close();
        audioContextRef.current = null;
    }

    setIsStreaming(false);
    setIsConnected(false);
    setVolume(0);
    setTranscript(null);
  }, []);

  return {
    isStreaming,
    isConnected,
    volume,
    transcript,
    startStream,
    stopStream
  };
}

