import React, { useEffect, useState } from 'react';
import { InventoryItem, Badge, WasteMetrics } from '../types';

interface InventoryOverlayProps {
  items: InventoryItem[];
  badges: Badge[];
  metrics: WasteMetrics;
  isStreaming: boolean;
  isConnected: boolean;
  volume: number;
  transcript: { role: 'user' | 'model'; text: string } | null;
  onToggleStream: () => void;
  onExit: () => void;
}

export const InventoryOverlay: React.FC<InventoryOverlayProps> = ({
  items,
  badges,
  metrics,
  isStreaming,
  isConnected,
  volume,
  transcript,
  onToggleStream,
  onExit
}) => {
  const [latestBadge, setLatestBadge] = useState<Badge | null>(null);
  const [latestItem, setLatestItem] = useState<InventoryItem | null>(null);

  // Calculate Rank based on total XP (Sum of all badges + items count * 10)
  const totalXP = badges.reduce((acc, b) => acc + b.xp, 0) + (items.length * 50);
  const nextRankXP = Math.ceil((totalXP + 1) / 1000) * 1000;
  const rankProgress = (totalXP % 1000) / 1000;
  const currentRank = totalXP < 1000 ? "RECRUIT" : totalXP < 2000 ? "LOGISTICS SPECIALIST" : "SUPPLY COMMANDER";

  // Detect new items to show bounding box briefly
  useEffect(() => {
    if (items.length > 0) {
      const newItem = items[items.length - 1];
      setLatestItem(newItem);
      // Hide bounding box after 3 seconds
      const timer = setTimeout(() => setLatestItem(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [items]);

  useEffect(() => {
    if (badges.length > 0) {
      setLatestBadge(badges[badges.length - 1]);
      const timer = setTimeout(() => setLatestBadge(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [badges]);

  return (
    <div className="absolute inset-0 z-10 flex flex-col justify-between safe-area-inset overflow-hidden">

      {/* --- Scan Line Effect --- */}
      {isStreaming && (
        <div className="absolute inset-0 pointer-events-none opacity-10 bg-scan-lines z-0" />
      )}
      <style>{`
        .bg-scan-lines {
          background: linear-gradient(to bottom, transparent 50%, rgba(34, 197, 94, 0.5) 50%);
          background-size: 100% 4px;
          animation: scan 0.5s linear infinite;
        }
        @keyframes scan {
          0% { transform: translateY(0); }
          100% { transform: translateY(4px); }
        }
        @keyframes bounce-in {
            0% { transform: scale(0.5); opacity: 0; }
            80% { transform: scale(1.1); opacity: 1; }
            100% { transform: scale(1); opacity: 1; }
        }
        .animate-bounce-in {
            animation: bounce-in 0.5s ease-out forwards;
        }
        @keyframes fade-in-up {
            from { opacity: 0; transform: translateY(5px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-in-up {
            animation: fade-in-up 0.3s ease-out forwards;
        }
      `}</style>

      {/* --- Bounding Box Overlay (Target Lock) --- */}
      {latestItem && latestItem.boundingBox && (
        <div 
            className="absolute z-20 pointer-events-none transition-all duration-300"
            style={{
                top: `${latestItem.boundingBox.ymin / 10}%`,
                left: `${latestItem.boundingBox.xmin / 10}%`,
                height: `${(latestItem.boundingBox.ymax - latestItem.boundingBox.ymin) / 10}%`,
                width: `${(latestItem.boundingBox.xmax - latestItem.boundingBox.xmin) / 10}%`,
            }}
        >
            {/* SVG Tactical Corners */}
            <svg className="absolute inset-0 w-full h-full overflow-visible">
                <defs>
                    <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
                        <feGaussianBlur stdDeviation="2" result="coloredBlur"/>
                        <feMerge>
                            <feMergeNode in="coloredBlur"/>
                            <feMergeNode in="SourceGraphic"/>
                        </feMerge>
                    </filter>
                </defs>
                {/* Top Left */}
                <path d="M0 20 V0 H20" fill="none" stroke="#22c55e" strokeWidth="2" filter="url(#glow)" vectorEffect="non-scaling-stroke" />
                {/* Top Right */}
                <path d="M100% 20 V0 Hcalc(100% - 20px)" fill="none" stroke="#22c55e" strokeWidth="2" filter="url(#glow)" style={{ transform: 'translateX(-100%)' }} transform-origin="top right" />
                {/* Bottom Left */}
                <path d="M0 calc(100% - 20px) V100% H20" fill="none" stroke="#22c55e" strokeWidth="2" filter="url(#glow)" />
                {/* Bottom Right */}
                <path d="M100% calc(100% - 20px) V100% Hcalc(100% - 20px)" fill="none" stroke="#22c55e" strokeWidth="2" filter="url(#glow)" />
            </svg>

            {/* Manual corner fallback/reinforcement for dynamic sizing */}
            <div className="absolute top-0 left-0 w-4 h-4 border-t-2 border-l-2 border-green-500"></div>
            <div className="absolute top-0 right-0 w-4 h-4 border-t-2 border-r-2 border-green-500"></div>
            <div className="absolute bottom-0 left-0 w-4 h-4 border-b-2 border-l-2 border-green-500"></div>
            <div className="absolute bottom-0 right-0 w-4 h-4 border-b-2 border-r-2 border-green-500"></div>

            {/* Center Crosshair */}
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-4 h-4 flex items-center justify-center opacity-50">
                <div className="w-full h-[1px] bg-green-500"></div>
                <div className="h-full w-[1px] bg-green-500 absolute"></div>
            </div>

            {/* Animated Label */}
            <div className="absolute -top-8 left-0 animate-fade-in-up">
                 <div className="bg-green-600/90 text-black text-[10px] font-black px-3 py-1 uppercase tracking-widest shadow-[0_0_15px_rgba(34,197,94,0.5)] flex items-center gap-2 border border-green-400">
                    <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse border border-red-900"></span>
                    TARGET: {latestItem.name}
                 </div>
            </div>

            {/* Bottom Info */}
            <div className="absolute -bottom-6 right-0 animate-fade-in-up" style={{ animationDelay: '0.1s' }}>
                <div className="bg-black/80 text-green-400 text-[10px] font-mono px-2 py-0.5 border border-green-500/30 flex gap-2">
                    <span>WT: {latestItem.weight}LB</span>
                    <span className="text-gray-500">|</span>
                    <span>{latestItem.condition}</span>
                </div>
            </div>
        </div>
      )}

      {/* --- Top HUD: Rank & Status --- */}
      <div className="flex justify-between items-start p-4 pointer-events-none relative z-30">

        {/* Left: Rank & XP */}
        <div className="flex flex-col gap-1 bg-black/40 p-2 rounded border-l-2 border-yellow-500 backdrop-blur-sm">
            <div className="text-[10px] text-yellow-500 uppercase font-bold tracking-widest">Current Rank</div>
            <div className="text-sm text-white font-black uppercase">{currentRank}</div>
            <div className="w-32 h-1 bg-gray-700 mt-1 relative">
                <div className="absolute left-0 top-0 h-full bg-yellow-500 transition-all duration-1000" style={{ width: `${rankProgress * 100}%` }} />
            </div>
            <div className="text-[9px] text-gray-400 text-right">{totalXP} / {nextRankXP} XP</div>
        </div>

        {/* Right: Connection Status & Exit */}
        <div className="flex flex-col items-end gap-2 pointer-events-auto">
           <button onClick={onExit} className="bg-red-900/50 hover:bg-red-900 border border-red-500 text-red-200 px-3 py-1 rounded text-xs font-bold uppercase tracking-wider mb-2">
             Abort Mission
           </button>
           <div className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-widest flex items-center gap-2 ${isConnected ? 'bg-green-500/20 text-green-400 border border-green-500/50' : 'bg-red-500/20 text-red-400 border border-red-500/50'}`}>
