      </div>

      {/* --- Middle Layer: Badge Popups --- */}
      <div className="flex-grow flex items-center justify-center pointer-events-none z-40">
        {latestBadge && (
            <div className="animate-bounce-in bg-gradient-to-br from-yellow-900/90 to-black/90 border-2 border-yellow-400 rounded-2xl p-6 text-center shadow-[0_0_50px_rgba(234,179,8,0.3)] backdrop-blur-md">
