                <div className="inline-block bg-yellow-500 text-black font-bold px-3 py-1 rounded-full text-sm">+{latestBadge.xp} XP</div>
            </div>
        )}
      </div>

      {/* --- Bottom HUD --- */}
      <div className="relative w-full px-4 pb-6 flex items-end justify-center pointer-events-none z-30">

        {/* Captions (Bottom Center) */}
        <div className="absolute bottom-24 flex flex-col items-center w-full px-8">
            {transcript && (
                <div className={`text-center px-4 py-2 rounded-lg backdrop-blur-md max-w-full border shadow-lg transition-all ${transcript.role === 'model' ? 'bg-cyan-900/60 text-cyan-100 border-cyan-500/50' : 'bg-gray-800/60 text-gray-200 border-gray-600/50'}`}>
                    <span className="text-[9px] uppercase font-bold opacity-70 block mb-1 tracking-widest">{transcript.role === 'model' ? 'LOGISTICS HQ' : 'FIELD OP'}</span>
                    <span className="text-sm font-medium leading-snug font-mono">"{transcript.text}"</span>
                </div>
            )}
        </div>

        {/* Main Mic Button (Bottom Center) */}
        <div className="pointer-events-auto relative z-50">
            <button 
                onClick={onToggleStream}
                className={`relative group rounded-full w-20 h-20 flex items-center justify-center transition-all ${isStreaming ? 'bg-red-500/20 hover:bg-red-500/40' : 'bg-white/10 hover:bg-white/20'}`}
            >
                {isStreaming && (
                <div 
                    className="absolute inset-0 rounded-full border-2 border-green-500 opacity-60"
                    style={{ transform: `scale(${1 + volume * 1.5})`, transition: 'transform 0.1s ease-out' }}
                />
                )}

                <div className={`z-10 w-16 h-16 rounded-full flex items-center justify-center transition-colors ${isStreaming ? 'bg-red-500 shadow-lg shadow-red-500/50' : 'bg-green-500 shadow-[0_0_20px_rgba(34,197,94,0.5)]'}`}>
                {isStreaming ? (
                    <div className="w-6 h-6 bg-white rounded-sm" />
                ) : (
                    <svg className="w-8 h-8 text-white ml-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                )}
                </div>
            </button>
        </div>

        {/* Floating Inventory Stack (Bottom Right) */}
        <div className="absolute bottom-4 right-4 w-48 h-32 flex flex-col justify-end pointer-events-none">
             <div className="relative w-full h-full">
                {items.length === 0 && (
                    <div className="absolute bottom-0 right-0 bg-black/60 p-2 text-[10px] text-gray-500 rounded border border-gray-800">NO ASSETS</div>
                )}
                {/* Render items in a stack */}
                {[...items].slice(-4).map((item, idx, arr) => {
                    // 0 is oldest in this slice, arr.length-1 is newest
                    const reverseIdx = arr.length - 1 - idx; // 0 is newest
                    return (
                        <div 
                            key={item.id} 
                            className="absolute bottom-0 right-0 w-full transition-all duration-500 ease-out"
                            style={{ 
                                transform: `translateY(-${reverseIdx * 12}px) scale(${1 - (reverseIdx * 0.05)})`,
                                opacity: 1 - (reverseIdx * 0.2),
                                zIndex: idx
                            }}
                        >
                            <div className="bg-gray-900/90 backdrop-blur-sm border-l-4 border-cyan-500 p-2 rounded shadow-lg flex justify-between items-center">
                                <div className="overflow-hidden">
                                    <div className="text-cyan-200 font-mono text-xs truncate font-bold uppercase">{item.name}</div>
                                    <div className="text-[9px] text-gray-400">ID: {item.id.slice(0,4)}</div>
                                </div>
                                <div className="text-right">
                                    <div className="text-[10px] text-white font-bold">{item.weight} lb</div>
                                </div>
                            </div>
                        </div>
                    );
                })}
             </div>
        </div>

      </div>

    </div>
  );
};

