import React, { useState, useRef, useCallback } from 'react';
import { 
  GoogleGenAI, 
  LiveServerMessage, 
  Modality, 
  FunctionDeclaration, 
  Type, 
  Blob 
} from '@google/genai';
import { InventoryItem } from '../types';
import { calculateDiversionMetrics } from '../services/wasteDiversionLogic';

// --- Types & Config ---

interface UseGeminiLiveProps {
  videoRef: React.RefObject<HTMLVideoElement>;
  onItemLogged: (item: InventoryItem) => void;
  onDetect: (item: InventoryItem) => void;
}

const MODEL_NAME = 'gemini-2.5-flash-native-audio-preview-09-2025';

const SYSTEM_INSTRUCTION = `
Role: You are a Master Surveyor using the Joint Travel Regulations (JTR) Table of Measurements.

INTERROGATION MODE: Do not just log items. Validate them.
- Table: "I see a dining table. Does it have extension leaves? How many chairs?"
- Sofa: "Is that a sleeper sofa or standard? Any reclining sections?"
- Dresser: "Is that a single or double dresser? Is there a mirror packed separately?"

BOX ESTIMATION: For every storage item (bookcase, dresser), calculate Carton Count.
- "That bookcase is 3ft wide. You'll need approx. 4 Small Cartons (1.5 cu ft) for those books."
- Use the 'cartonCount' parameter in 'log_item'.

VISUAL TARGETING:
- Continuously analyze the video stream.
- When you see a furniture item, call the 'detect_item' tool to draw a bounding box.
- Then proceed with interrogation.

TONE: Professional, authoritative, efficient. Use terms like "Affirmative", "Asset Verified".
`;

// --- Helper: Audio Encoding/Decoding ---

function createBlob(data: Float32Array): Blob {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) {
    int16[i] = data[i] * 32768;
  }

  // Convert Int16Array to a binary string manually for btoa
  let binary = '';
  const bytes = new Uint8Array(int16.buffer);
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }

  return {
    data: btoa(binary),
    mimeType: 'audio/pcm;rate=16000',
  };
}

function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

async function blobToBase64(blob: globalThis.Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
}

// --- Tools Declarations ---

const logItemTool: FunctionDeclaration = {
  name: 'log_item',
  description: 'Log a household item into the inventory database after validation.',
  parameters: {
    type: Type.OBJECT,
    properties: {
