  },
};

const detectItemTool: FunctionDeclaration = {
  name: 'detect_item',
  description: 'Draw a bounding box around a detected item to show the user you see it.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      label: { type: Type.STRING, description: "What did you see? (e.g. 'Dresser')" },
