// --- The Hook ---

export function useGeminiLive({ videoRef, onItemLogged, onDetect }: UseGeminiLiveProps) {
  const [isStreaming, setIsStreaming] = useState(false);
  const [isConnected, setIsConnected] = useState(false);
  const [volume, setVolume] = useState(0); 
  const [transcript, setTranscript] = useState<{role: 'user' | 'model', text: string} | null>(null);

  // Refs for audio handling to avoid re-renders
  const audioContextRef = useRef<AudioContext | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Stream Ref
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const videoIntervalRef = useRef<number | null>(null);

  const startStream = useCallback(async () => {
    if (!process.env.API_KEY) {
      console.error("No API Key found");
      return;
    }

    try {
      setIsStreaming(true);

      // 1. Initialize Audio Contexts
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      const inputCtx = new AudioContextClass({ sampleRate: 16000 });
      const outputCtx = new AudioContextClass({ sampleRate: 24000 }); 

      inputAudioContextRef.current = inputCtx;
      audioContextRef.current = outputCtx;
      nextStartTimeRef.current = 0;

      // 2. Setup Mic Stream
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const source = inputCtx.createMediaStreamSource(stream);
      const analyzer = inputCtx.createAnalyser(); 
      analyzer.fftSize = 256;

      const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);

      scriptProcessor.onaudioprocess = (e) => {
        if (!sessionPromiseRef.current) return;

        const inputData = e.inputBuffer.getChannelData(0);

        // Simple volume meter
        let sum = 0;
        for(let i=0; i<inputData.length; i++) sum += inputData[i] * inputData[i];
        setVolume(Math.sqrt(sum / inputData.length));

        const pcmBlob = createBlob(inputData);
        sessionPromiseRef.current.then(session => {
            session.sendRealtimeInput({ media: pcmBlob });
        });
      };

      source.connect(analyzer);
      source.connect(scriptProcessor);
      scriptProcessor.connect(inputCtx.destination);

      // 3. Connect to Gemini Live
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const sessionPromise = ai.live.connect({
        model: MODEL_NAME,
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          tools: [{ functionDeclarations: [logItemTool, detectItemTool] }],
          systemInstruction: SYSTEM_INSTRUCTION,
        },
        callbacks: {
          onopen: () => {
            console.log("Gemini Live Connected");
            setIsConnected(true);

            // *** KICKSTART THE CONVERSATION ***
            setTimeout(() => {
                sessionPromise.then(session => 
                    session.sendRealtimeInput({ text: "SYSTEM: Scanner initialized. Introduce yourself to the Service Member." })
                );
            }, 500);
          },
          onmessage: async (message: LiveServerMessage) => {
             // Handle Transcriptions
             const serverContent = message.serverContent;
             if (serverContent?.outputTranscription?.text) {
                 setTranscript({ role: 'model', text: serverContent.outputTranscription.text });
             } else if (serverContent?.inputTranscription?.text) {
                 setTranscript({ role: 'user', text: serverContent.inputTranscription.text });
             }

             // Handle Audio Output
             const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
             if (audioData) {
               if (outputCtx.state === 'suspended') await outputCtx.resume();

               const decoded = decode(audioData);
               const audioBuffer = await decodeAudioData(decoded, outputCtx, 24000, 1);

               const node = outputCtx.createBufferSource();
               node.buffer = audioBuffer;
               node.connect(outputCtx.destination);

               const currentTime = outputCtx.currentTime;
               const startTime = Math.max(currentTime, nextStartTimeRef.current);
               node.start(startTime);
               nextStartTimeRef.current = startTime + audioBuffer.duration;

               sourcesRef.current.add(node);
               node.onended = () => sourcesRef.current.delete(node);
             }

             // Handle Tool Calls
             if (message.toolCall) {
                console.log("Tool Call Received:", message.toolCall);
                const responses = [];

                for (const fc of message.toolCall.functionCalls) {
                    let result = { result: 'ok' };

                    if (fc.name === 'log_item') {
                        const { name, weight, status, condition, cartonCount, ymin, xmin, ymax, xmax } = fc.args as any;
                        const metrics = calculateDoDSavings(name, weight, status);

                        const newItem: InventoryItem = {
                            id: crypto.randomUUID(),
                            name,
                            weight: metrics.estimatedWeight,
                            status: (status as any) || 'KEEP',
                            condition: condition || 'Good',
                            timestamp: Date.now(),
                            tariffCredit: metrics.tariffCredit,
                            carbonSaved: metrics.carbonSaved,
                            cartonCount: cartonCount || 0,
                            boundingBox: (ymin !== undefined && xmin !== undefined) ? { ymin, xmin, ymax, xmax } : undefined
                        };

                        onItemLogged(newItem);
                        result = { result: `Asset ${name} verified and logged.` };
                    } 
                    else if (fc.name === 'detect_item') {
                        const { label, ymin, xmin, ymax, xmax } = fc.args as any;
                        const detected: InventoryItem = {
                            id: 'temp-' + Date.now(),
                            name: label,
                            weight: 0,
                            status: 'DETECTED',
                            condition: 'Scanning...',
                            timestamp: Date.now(),
                            tariffCredit: 0,
                            carbonSaved: 0,
                            cartonCount: 0,
                            boundingBox: { ymin, xmin, ymax, xmax }
                        };
                        onDetect(detected);
                        result = { result: `Visual target acquired: ${label}` };
                    }

                    responses.push({
                        id: fc.id,
                        name: fc.name,
                        response: result
                    });
                }

                sessionPromise.then(session => {
                    session.sendToolResponse({ functionResponses: responses });
                });
             }
          },
          onclose: () => {
            console.log("Gemini Live Closed");
            setIsConnected(false);
          },
          onerror: (err) => {
            console.error("Gemini Live Error", err);
            setIsConnected(false);
          }
        }
      });

      sessionPromiseRef.current = sessionPromise;

      // 4. Start Video Stream (2 FPS)
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');

      const intervalId = window.setInterval(async () => {
        if (!videoRef.current || !sessionPromiseRef.current) return;
        const video = videoRef.current;
        if (video.videoWidth === 0) return;

        const scale = 0.5;
        canvas.width = video.videoWidth * scale;
        canvas.height = video.videoHeight * scale;

        ctx?.drawImage(video, 0, 0, canvas.width, canvas.height);

        canvas.toBlob(async (blob) => {
            if (!blob) return;
            const base64 = await blobToBase64(blob);
            sessionPromiseRef.current?.then(session => {
                session.sendRealtimeInput({
                    media: {
                        mimeType: 'image/jpeg',
                        data: base64
                    }
                });
            });
        }, 'image/jpeg', 0.6);

      }, 500);

      videoIntervalRef.current = intervalId;

    } catch (e) {
      console.error("Failed to start stream", e);
      setIsStreaming(false);
    }
  }, [videoRef, onItemLogged, onDetect]);

  const stopStream = useCallback(() => {
    if (sessionPromiseRef.current) {
        sessionPromiseRef.current.then(session => session.close());
        sessionPromiseRef.current = null;
    }

    if (videoIntervalRef.current) {
        clearInterval(videoIntervalRef.current);
        videoIntervalRef.current = null;
    }

    if (inputAudioContextRef.current) {
        inputAudioContextRef.current.close();
        inputAudioContextRef.current = null;
    }

    if (audioContextRef.current) {
        audioContextRef.current.close();
        audioContextRef.current = null;
    }

    setIsStreaming(false);
    setIsConnected(false);
    setVolume(0);
    setTranscript(null);
  }, []);

  return {
    isStreaming,
    isConnected,
    volume,
    transcript,
    startStream,
    stopStream
  };
}

import React, { useEffect, useRef, useState } from 'react';
import { InventoryItem, WasteMetrics, UserProfile } from './types';
import { useGeminiLive } from './hooks/useGeminiLive';
import { InventoryOverlay } from './components/InventoryOverlay';
import { IntroScreen } from './components/IntroScreen';
import { OnboardingTour } from './components/OnboardingTour';
import { Dashboard } from './components/Dashboard';

type ViewState = 'INTRO' | 'DASHBOARD' | 'SCANNER';

export default function App() {
  const videoRef = useRef<HTMLVideoElement>(null);

  // App View State
  const [view, setView] = useState<ViewState>('INTRO');
  const [showTour, setShowTour] = useState(false);

  // User Profile State
  const [userProfile, setUserProfile] = useState<UserProfile>({
      rank: 'E-1',
      moveType: 'PCS',
      weightAllowance: 4000
  });

  // Persistent State
  const [inventory, setInventory] = useState<InventoryItem[]>(() => {
    const saved = localStorage.getItem('moveguru_inventory');
    return saved ? JSON.parse(saved) : [];
  });

  // Ephemeral State for Visual Targeting
  const [detectedItem, setDetectedItem] = useState<InventoryItem | null>(null);

  // Save on Change
  useEffect(() => {
    localStorage.setItem('moveguru_inventory', JSON.stringify(inventory));
  }, [inventory]);

  // Derived Metrics
  const metrics: WasteMetrics = {
    totalWeight: inventory.reduce((acc, item) => acc + item.weight, 0),
    totalCarbonSaved: inventory.reduce((acc, item) => acc + item.carbonSaved, 0),
    totalTariffCredit: inventory.reduce((acc, item) => acc + item.tariffCredit, 0),
    inventoryCount: inventory.length,
    divertedWeight: inventory.reduce((acc, item) => item.status !== 'KEEP' ? acc + item.weight : acc, 0)
  };

  const handleLogin = (profile: UserProfile) => {
      setUserProfile(profile);
      setView('DASHBOARD');
      // Show tour on first login session (simplified logic)
      setShowTour(true);
  };

  const handleItemLogged = (item: InventoryItem) => {
    setInventory(prev => [...prev, item]);
  };

  const handleItemDetected = (item: InventoryItem) => {
    setDetectedItem(item);
  };

  const { isStreaming, isConnected, volume, transcript, startStream, stopStream } = useGeminiLive({
    videoRef,
    onItemLogged: handleItemLogged,
    onDetect: handleItemDetected
  });

  // Setup Video Stream
  useEffect(() => {
    let stream: MediaStream | null = null;

    async function setupCamera() {
      if (view === 'SCANNER' && videoRef.current) {
        try {
          stream = await navigator.mediaDevices.getUserMedia({ 
            video: { 
              facingMode: 'environment',
              width: { ideal: 1280 },
              height: { ideal: 720 }
            } 
          });
          videoRef.current.srcObject = stream;
        } catch (err) {
          console.error("Camera access denied", err);
        }
      }
    }

    if (view === 'SCANNER') {
      setupCamera();
    } else {
        if (videoRef.current && videoRef.current.srcObject) {
            const tracks = (videoRef.current.srcObject as MediaStream).getTracks();
            tracks.forEach(track => track.stop());
            videoRef.current.srcObject = null;
        }
    }

    return () => {
        if (stream) {
            stream.getTracks().forEach(t => t.stop());
        }
    };
  }, [view]);

  // Handlers
  const toggleStream = () => {
    if (isStreaming) {
      stopStream();
    } else {
      startStream();
    }
  };

  const exitScanner = () => {
    stopStream();
    setView('DASHBOARD');
  };

  return (
    <div className="relative w-screen h-screen bg-black overflow-hidden font-sans">

      {view === 'INTRO' && (
        <IntroScreen onLogin={handleLogin} />
      )}

      {view === 'DASHBOARD' && (
        <Dashboard 
          inventory={inventory}
          badges={[]} // Badges deprecated in Pro mode
          metrics={metrics}
          onDeploy={() => setView('SCANNER')}
          onLogout={() => setView('INTRO')}
        />
      )}

      {view === 'SCANNER' && (
        <>
            {/* 1. Camera View */}
            <video 
                ref={videoRef}
                autoPlay 
                playsInline 
                muted 
                className="absolute inset-0 w-full h-full object-cover opacity-80"
            />

            {/* 2. Grid Overlay */}
            <div className="absolute inset-0 pointer-events-none" style={{
                backgroundImage: 'linear-gradient(rgba(0, 255, 0, 0.03) 1px, transparent 1px), linear-gradient(90deg, rgba(0, 255, 0, 0.03) 1px, transparent 1px)',
                backgroundSize: '40px 40px'
            }} />

            {/* 3. Vignette */}
            <div className="absolute inset-0 pointer-events-none bg-[radial-gradient(circle_at_center,transparent_0%,rgba(0,0,0,0.6)_100%)]" />

            {/* 4. UI Layer */}
            <InventoryOverlay 
                items={inventory}
                detectedItem={detectedItem}
                metrics={metrics}
                userProfile={userProfile}
                isStreaming={isStreaming}
                isConnected={isConnected}
                volume={volume}
                transcript={transcript}
                onToggleStream={toggleStream}
                onExit={exitScanner}
            />

            {/* 5. Onboarding Tour (Overlay on top of Scanner) */}
            {showTour && (
                <OnboardingTour onClose={() => setShowTour(false)} />
            )}
        </>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { UserProfile } from '../types';

interface IntroScreenProps {
  onLogin: (profile: UserProfile) => void;
}

const RANKS = [
  { label: 'E-1 to E-4', allowance: 4000 },
  { label: 'E-5', allowance: 7000 },
  { label: 'E-6', allowance: 8000 },
  { label: 'E-7', allowance: 10000 },
  { label: 'E-8', allowance: 12000 },
  { label: 'E-9', allowance: 14000 },
  { label: 'O-1 to O-3', allowance: 12000 },
  { label: 'O-4', allowance: 14000 },
  { label: 'O-5', allowance: 16000 },
  { label: 'O-6', allowance: 18000 },
];

export const IntroScreen: React.FC<IntroScreenProps> = ({ onLogin }) => {
  const [step, setStep] = useState<number>(0);
  const [profile, setProfile] = useState<UserProfile>({
    rank: 'E-5',
    moveType: 'PCS',
    weightAllowance: 7000
  });

  const handleRankChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const selected = RANKS.find(r => r.label === e.target.value);
    setProfile(prev => ({
      ...prev,
      rank: e.target.value,
      weightAllowance: selected ? selected.allowance : 7000
    }));
  };

  const nextStep = () => setStep(prev => prev + 1);

  const requestPermissions = async () => {
    try {
      await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      nextStep(); // Go to Profile after permissions
    } catch (err) {
      alert("Microphone and Camera permissions are required for the Asset Conversion Engine.");
    }
  };

  const handleComplete = () => {
    onLogin(profile);
  };

  return (
    <div className="absolute inset-0 bg-black flex flex-col items-center justify-center p-6 z-50 overflow-hidden font-sans">

      {/* Professional Grid Background */}
      <div className="absolute inset-0 pointer-events-none" 
           style={{
             backgroundImage: 'linear-gradient(rgba(16, 185, 129, 0.05) 1px, transparent 1px), linear-gradient(90deg, rgba(16, 185, 129, 0.05) 1px, transparent 1px)',
             backgroundSize: '40px 40px'
           }} 
      />

      {/* Step 0: Splash */}
      {step === 0 && (
        <div className="z-10 text-center animate-fade-in-up">
          <div className="text-green-500 text-xs font-mono mb-4 tracking-[0.3em] uppercase">Department of Defense</div>
          <h1 className="text-6xl font-black text-white mb-2 tracking-tighter">MOVE<span className="text-green-600">GURU</span></h1>
          <p className="text-gray-400 text-sm mb-12 uppercase tracking-widest">Asset Transparency & Compliance Engine</p>

          <button 
            onClick={nextStep}
            className="px-8 py-3 bg-white text-black font-bold uppercase tracking-wider rounded hover:bg-gray-200 transition-colors"
          >
            Initialize System
          </button>
        </div>
      )}

      {/* Step 1: System Authorization (Permissions) */}
      {step === 1 && (
        <div className="z-10 w-full max-w-md bg-gray-900/90 backdrop-blur-md border border-gray-700 p-8 rounded-lg shadow-2xl animate-fade-in-up">
           <h2 className="text-xl font-bold text-white mb-6 uppercase border-b border-gray-700 pb-2">System Authorization</h2>

           <div className="space-y-4 mb-8">
             <div className="flex items-center gap-4 p-4 bg-black/50 rounded border border-gray-800">
               <div className="w-10 h-10 rounded-full bg-gray-800 flex items-center justify-center text-green-500">
                 <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
               </div>
               <div>
                 <div className="text-sm font-bold text-white">Visual Optical Sensor</div>
                 <div className="text-xs text-gray-500">Required for Asset Identification</div>
               </div>
             </div>

             <div className="flex items-center gap-4 p-4 bg-black/50 rounded border border-gray-800">
               <div className="w-10 h-10 rounded-full bg-gray-800 flex items-center justify-center text-green-500">
                 <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
               </div>
               <div>
                 <div className="text-sm font-bold text-white">Audio Input Array</div>
                 <div className="text-xs text-gray-500">Required for Officer Interrogation</div>
               </div>
             </div>
           </div>

           <button 
              onClick={requestPermissions}
              className="w-full py-4 bg-green-600 hover:bg-green-500 text-black font-bold uppercase tracking-wider rounded transition-colors shadow-[0_0_20px_rgba(22,163,74,0.3)]"
            >
              Authorize Access
            </button>
        </div>
      )}

      {/* Step 2: Profile Configuration */}
      {step === 2 && (
        <div className="z-10 w-full max-w-md bg-gray-900/90 backdrop-blur-md border border-gray-700 p-8 rounded-lg shadow-2xl animate-fade-in-up">
          <h2 className="text-xl font-bold text-white mb-6 uppercase border-b border-gray-700 pb-2">Profile Configuration</h2>

          <div className="space-y-6">
            <div>
              <label className="block text-[10px] text-green-500 uppercase tracking-widest mb-2">Service Rank / Grade</label>
              <select 
                value={profile.rank}
                onChange={handleRankChange}
                className="w-full bg-black border border-gray-700 text-white p-3 rounded focus:border-green-500 focus:outline-none transition-colors"
              >
                {RANKS.map(r => (
                  <option key={r.label} value={r.label}>{r.label} (Max {r.allowance.toLocaleString()} lbs)</option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-[10px] text-green-500 uppercase tracking-widest mb-2">Operation Type</label>
              <div className="grid grid-cols-3 gap-2">
                {['PCS', 'RETIREMENT', 'SEPARATION'].map((type) => (
                  <button
                    key={type}
                    onClick={() => setProfile(prev => ({ ...prev, moveType: type as any }))}
                    className={`text-[10px] font-bold py-3 rounded border transition-all ${profile.moveType === type ? 'bg-green-600 border-green-500 text-black' : 'bg-black border-gray-700 text-gray-400 hover:border-gray-500'}`}
                  >
                    {type}
                  </button>
                ))}
              </div>
            </div>

            <button 
              onClick={handleComplete}
              className="w-full py-4 mt-4 bg-green-600 hover:bg-green-500 text-black font-bold uppercase tracking-wider rounded transition-colors"
            >
              Confirm & Launch
            </button>
          </div>
        </div>
      )}

      <div className="absolute bottom-6 text-[10px] text-gray-600 font-mono">
        UNCLASSIFIED // FOUO // V3.0-PRO
      </div>

      <style>{`
        @keyframes fade-in-up {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-in-up {
            animation: fade-in-up 0.5s ease-out forwards;
        }
      `}</style>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { InventoryItem, WasteMetrics, UserProfile } from '../types';

interface InventoryOverlayProps {
  items: InventoryItem[];
  detectedItem: InventoryItem | null;
  metrics: WasteMetrics;
  userProfile: UserProfile;
  isStreaming: boolean;
  isConnected: boolean;
  volume: number;
  transcript: { role: 'user' | 'model'; text: string } | null;
  onToggleStream: () => void;
  onExit: () => void;
}

export const InventoryOverlay: React.FC<InventoryOverlayProps> = ({
  items,
  detectedItem,
  metrics,
  userProfile,
  isStreaming,
  isConnected,
  volume,
  transcript,
  onToggleStream,
  onExit
}) => {
  const [latestItem, setLatestItem] = useState<InventoryItem | null>(null);
  const [milestone, setMilestone] = useState<string | null>(null);

  // Calculate Capacity Percentage
  const capacityUsedPercent = Math.min((metrics.totalWeight / userProfile.weightAllowance) * 100, 100);

  // Calculate Diversion Percentage (ISWM)
  const diversionPercent = metrics.totalWeight > 0 
    ? (metrics.divertedWeight / metrics.totalWeight) * 100 
    : 0;

  // Effect to handle both new logged items AND ephemeral detected items
  useEffect(() => {
    // Priority: Detected item (ephemeral) > Newest logged item
    if (detectedItem) {
        setLatestItem(detectedItem);
        // Clear ephemeral detection visual after 2s if no updates
        const timer = setTimeout(() => setLatestItem(null), 2000);
        return () => clearTimeout(timer);
    } else if (items.length > 0) {
      const newItem = items[items.length - 1];
      // Only set if we don't have a transient detection showing
      setLatestItem(newItem);

      // Milestone Check: Every 5th item
      if (items.length % 5 === 0) {
          setMilestone("High Value Asset");
          setTimeout(() => setMilestone(null), 4000);
      }

      const timer = setTimeout(() => setLatestItem(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [items, detectedItem]);

  return (
    <div className="absolute inset-0 z-10 flex flex-col justify-between safe-area-inset overflow-hidden">

      {/* --- Visual Effects --- */}
      {isStreaming && (
        <div className="absolute inset-0 pointer-events-none opacity-10 bg-scan-lines z-0" />
      )}
      <style>{`
        .bg-scan-lines {
          background: linear-gradient(to bottom, transparent 50%, rgba(34, 197, 94, 0.5) 50%);
          background-size: 100% 4px;
          animation: scan 0.5s linear infinite;
        }
        @keyframes scan {
          0% { transform: translateY(0); }
          100% { transform: translateY(4px); }
        }
        @keyframes fade-in-up {
            from { opacity: 0; transform: translateY(5px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-in-up {
            animation: fade-in-up 0.3s ease-out forwards;
        }
      `}</style>

      {/* --- Milestone Notification --- */}
      {milestone && (
          <div className="absolute top-24 left-1/2 -translate-x-1/2 z-50 animate-fade-in-up">
              <div className="bg-yellow-500/20 backdrop-blur-md border border-yellow-500 text-yellow-500 px-6 py-2 rounded-full shadow-[0_0_30px_rgba(234,179,8,0.3)] flex items-center gap-3">
                  <div className="bg-yellow-500 text-black rounded-full p-1">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" /></svg>
                  </div>
                  <div>
                      <div className="text-[10px] font-bold uppercase tracking-widest">Milestone Unlocked</div>
                      <div className="text-sm font-black uppercase">{milestone}</div>
                  </div>
              </div>
          </div>
      )}

      {/* --- Bounding Box Overlay (Target Lock) --- */}
      {latestItem && latestItem.boundingBox && (
        <div 
            className="absolute z-20 pointer-events-none transition-all duration-300"
            style={{
                top: `${latestItem.boundingBox.ymin / 10}%`,
                left: `${latestItem.boundingBox.xmin / 10}%`,
                height: `${(latestItem.boundingBox.ymax - latestItem.boundingBox.ymin) / 10}%`,
                width: `${(latestItem.boundingBox.xmax - latestItem.boundingBox.xmin) / 10}%`,
            }}
        >
            <div className={`absolute inset-0 border border-dashed animate-pulse ${latestItem.status === 'DETECTED' ? 'border-yellow-500/50' : 'border-green-500/50'}`}></div>
            {/* SVG Tactical Corners */}
            <svg className="absolute inset-0 w-full h-full overflow-visible">
                <defs>
                    <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
                        <feGaussianBlur stdDeviation="2" result="coloredBlur"/>
                        <feMerge>
                            <feMergeNode in="coloredBlur"/>
                            <feMergeNode in="SourceGraphic"/>
                        </feMerge>
                    </filter>
                </defs>
                <path d="M0 20 V0 H20" fill="none" stroke={latestItem.status === 'DETECTED' ? '#eab308' : '#22c55e'} strokeWidth="2" filter="url(#glow)" vectorEffect="non-scaling-stroke" />
                <path d="M100% 20 V0 Hcalc(100% - 20px)" fill="none" stroke={latestItem.status === 'DETECTED' ? '#eab308' : '#22c55e'} strokeWidth="2" filter="url(#glow)" style={{ transform: 'translateX(-100%)' }} transform-origin="top right" />
                <path d="M0 calc(100% - 20px) V100% H20" fill="none" stroke={latestItem.status === 'DETECTED' ? '#eab308' : '#22c55e'} strokeWidth="2" filter="url(#glow)" />
                <path d="M100% calc(100% - 20px) V100% Hcalc(100% - 20px)" fill="none" stroke={latestItem.status === 'DETECTED' ? '#eab308' : '#22c55e'} strokeWidth="2" filter="url(#glow)" />
            </svg>
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-4 h-4 flex items-center justify-center opacity-50">
                <div className={`w-full h-[1px] ${latestItem.status === 'DETECTED' ? 'bg-yellow-500' : 'bg-green-500'}`}></div>
                <div className={`h-full w-[1px] absolute ${latestItem.status === 'DETECTED' ? 'bg-yellow-500' : 'bg-green-500'}`}></div>
            </div>

            <div className="absolute -top-8 left-0 animate-fade-in-up whitespace-nowrap">
                 <div className={`text-[10px] font-black px-3 py-1 uppercase tracking-widest flex items-center gap-2 border shadow-[0_0_15px_rgba(0,0,0,0.5)] ${latestItem.status === 'DETECTED' ? 'bg-yellow-600/90 text-black border-yellow-400' : 'bg-green-600/90 text-black border-green-400'}`}>
                    <span className={`w-2 h-2 rounded-full animate-pulse border border-red-900 ${latestItem.status === 'DETECTED' ? 'bg-white' : 'bg-red-500'}`}></span>
                    {latestItem.status === 'DETECTED' ? `TARGET: ${latestItem.name}` : `VERIFIED: ${latestItem.name}`}
                 </div>
            </div>

            {latestItem.status !== 'DETECTED' && (
                <div className="absolute -bottom-6 right-0 animate-fade-in-up whitespace-nowrap" style={{ animationDelay: '0.1s' }}>
                    <div className="bg-black/80 text-green-400 text-[10px] font-mono px-2 py-0.5 border border-green-500/30 flex gap-2">
                        <span>{latestItem.weight}LB</span>
                        <span className="text-gray-500">|</span>
                        <span>{latestItem.cartonCount && latestItem.cartonCount > 0 ? `${latestItem.cartonCount} CTNS` : 'BULK'}</span>
                    </div>
                </div>
            )}
        </div>
      )}

      {/* --- Professional Header (Meters) --- */}
      <div className="flex justify-between items-start p-4 pointer-events-none relative z-30 w-full bg-gradient-to-b from-black/80 to-transparent">

        {/* Left: ISWM Diversion Meter */}
        <div className="flex flex-col gap-1 w-48 iswm-target">
            <div className="flex justify-between items-baseline">
                <div className="text-[10px] text-green-500 uppercase font-bold tracking-widest">ISWM Diversion</div>
                <div className="text-[10px] text-white font-mono">{diversionPercent.toFixed(0)}% / 50%</div>
            </div>
            <div className="w-full h-2 bg-gray-800 rounded-full overflow-hidden border border-gray-700">
                <div 
                    className={`h-full transition-all duration-1000 ${diversionPercent >= 50 ? 'bg-green-500' : 'bg-yellow-500'}`} 
                    style={{ width: `${Math.min(diversionPercent, 100)}%` }} 
                />
            </div>
            <div className="text-[9px] text-gray-400">Total Diverted: {metrics.divertedWeight.toFixed(0)} lbs</div>
        </div>

        {/* Right: Capacity Utilization */}
        <div className="flex flex-col gap-1 w-48 items-end capacity-target">
             <div className="flex justify-between items-baseline w-full text-right">
                <div className="text-[10px] text-blue-500 uppercase font-bold tracking-widest">Weight Allowance</div>
                <div className="text-[10px] text-white font-mono">{metrics.totalWeight.toLocaleString()} / {userProfile.weightAllowance.toLocaleString()}</div>
            </div>
            <div className="w-full h-2 bg-gray-800 rounded-full overflow-hidden border border-gray-700">
                <div 
                    className={`h-full transition-all duration-1000 ${capacityUsedPercent > 90 ? 'bg-red-500' : 'bg-blue-500'}`} 
                    style={{ width: `${capacityUsedPercent}%` }} 
                />
            </div>
            <div className="text-[9px] text-gray-400 uppercase">{userProfile.rank} Entitlement</div>
        </div>
      </div>


      {/* --- Main Content Area --- */}
      <div className="flex-grow relative flex">
         {/* Center: System Status / Captions */}
         <div className="absolute inset-x-0 bottom-24 flex flex-col items-center justify-center px-8 z-30">
            {transcript && (
                <div className={`text-center px-6 py-3 rounded backdrop-blur-md max-w-xl border shadow-lg transition-all ${transcript.role === 'model' ? 'bg-green-900/60 text-green-50 border-green-500/50' : 'bg-gray-800/60 text-gray-200 border-gray-600/50'}`}>
                    <span className="text-[9px] uppercase font-bold opacity-70 block mb-1 tracking-widest text-left">{transcript.role === 'model' ? 'LOGISTICS OFFICER' : 'OPERATOR'}</span>
                    <span className="text-sm font-medium leading-snug font-mono text-left block">"{transcript.text}"</span>
                </div>
            )}
        </div>

        {/* Right: Glassmorphism Inventory List (Transparent Sidebar) */}
        <div className="absolute right-0 top-0 bottom-24 w-64 p-4 overflow-y-auto pointer-events-none manifest-target">
            <div className="space-y-2 flex flex-col items-end">
                {items.slice().reverse().map((item, idx) => (
                    <div 
                        key={item.id} 
                        className="bg-black/40 backdrop-blur-md border border-white/10 p-2 rounded w-full flex justify-between items-center text-right animate-fade-in-up"
                        style={{ animationDelay: `${idx * 0.05}s` }}
                    >
                         <div className="flex flex-col items-start overflow-hidden">
                             <span className="text-white text-xs font-bold truncate w-24 text-left">{item.name}</span>
                             <span className="text-[9px] text-gray-400 uppercase">{item.condition}</span>
                         </div>
                         <div className="flex flex-col items-end">
                             <span className="text-green-400 text-xs font-mono">{item.weight} lb</span>
                             {item.cartonCount && item.cartonCount > 0 && <span className="text-[9px] text-blue-300">{item.cartonCount} Box</span>}
                         </div>
                    </div>
                ))}
            </div>
        </div>
      </div>

      {/* --- Bottom Controls --- */}
      <div className="relative w-full px-4 pb-6 flex items-end justify-between pointer-events-none z-30 bg-gradient-to-t from-black/90 to-transparent pt-12">

        {/* Left: Exit */}
        <button onClick={onExit} className="pointer-events-auto flex items-center gap-2 text-gray-400 hover:text-white transition-colors">
             <div className="w-8 h-8 rounded border border-gray-600 flex items-center justify-center text-xs">ESC</div>
             <span className="text-[10px] uppercase tracking-widest">End Session</span>
        </button>

        {/* Center: Mic (Engagement Status) */}
        <div className="pointer-events-auto mic-target">
            <button 
                onClick={onToggleStream}
                className={`relative group rounded-full w-20 h-20 flex items-center justify-center transition-all ${isStreaming ? 'bg-red-500/10' : 'bg-white/5'}`}
            >
                {isStreaming && (
                <div 
                    className="absolute inset-0 rounded-full border border-green-500 opacity-60"
                    style={{ transform: `scale(${1 + volume * 1.5})`, transition: 'transform 0.1s ease-out' }}
                />
                )}

                <div className={`z-10 w-14 h-14 rounded-full flex items-center justify-center transition-colors border ${isStreaming ? 'bg-red-600 border-red-400 shadow-[0_0_20px_rgba(220,38,38,0.5)]' : 'bg-transparent border-green-500 text-green-500'}`}>
                {isStreaming ? (
                    <div className="w-4 h-4 bg-white rounded-sm" />
                ) : (
                    <svg className="w-6 h-6 ml-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                )}
                </div>
            </button>
            <div className="text-center mt-2 text-[9px] uppercase tracking-widest text-gray-500">{isStreaming ? 'Live' : 'Standby'}</div>
        </div>

        {/* Right: Connection */}
         <div className={`flex items-center gap-2 px-3 py-1 rounded border ${isConnected ? 'bg-green-900/20 border-green-800 text-green-500' : 'bg-red-900/20 border-red-800 text-red-500'}`}>
             <div className={`w-1.5 h-1.5 rounded-full ${isConnected ? 'bg-green-500 animate-pulse' : 'bg-red-500'}`} />
             <span className="text-[9px] font-bold uppercase">{isConnected ? 'SAT-LINK' : 'OFFLINE'}</span>
         </div>

      </div>

    </div>
  );
};

