                 <div className={`text-[10px] font-black px-3 py-1 uppercase tracking-widest flex items-center gap-2 border shadow-[0_0_15px_rgba(0,0,0,0.5)] ${latestItem.status === 'DETECTED' ? 'bg-yellow-600/90 text-black border-yellow-400' : 'bg-green-600/90 text-black border-green-400'}`}>
                    <span className={`w-2 h-2 rounded-full animate-pulse border border-red-900 ${latestItem.status === 'DETECTED' ? 'bg-white' : 'bg-red-500'}`}></span>
                    {latestItem.status === 'DETECTED' ? `TARGET: ${latestItem.name}` : `VERIFIED: ${latestItem.name}`}
                 </div>
            </div>

            {latestItem.status !== 'DETECTED' && (
                <div className="absolute -bottom-6 right-0 animate-fade-in-up whitespace-nowrap" style={{ animationDelay: '0.1s' }}>
                    <div className="bg-black/80 text-green-400 text-[10px] font-mono px-2 py-0.5 border border-green-500/30 flex gap-2">
                        <span>{latestItem.weight}LB</span>
                        <span className="text-gray-500">|</span>
                        <span>{latestItem.cartonCount && latestItem.cartonCount > 0 ? `${latestItem.cartonCount} CTNS` : 'BULK'}</span>
                    </div>
                </div>
            )}
        </div>
      )}

      {/* --- Professional Header (Meters) --- */}
      <div className="flex justify-between items-start p-4 pointer-events-none relative z-30 w-full bg-gradient-to-b from-black/80 to-transparent">

        {/* Left: ISWM Diversion Meter */}
        <div className="flex flex-col gap-1 w-48 iswm-target">
            <div className="flex justify-between items-baseline">
                <div className="text-[10px] text-green-500 uppercase font-bold tracking-widest">ISWM Diversion</div>
                <div className="text-[10px] text-white font-mono">{diversionPercent.toFixed(0)}% / 50%</div>
            </div>
            <div className="w-full h-2 bg-gray-800 rounded-full overflow-hidden border border-gray-700">
                <div 
                    className={`h-full transition-all duration-1000 ${diversionPercent >= 50 ? 'bg-green-500' : 'bg-yellow-500'}`} 
                    style={{ width: `${Math.min(diversionPercent, 100)}%` }} 
                />
            </div>
            <div className="text-[9px] text-gray-400">Total Diverted: {metrics.divertedWeight.toFixed(0)} lbs</div>
        </div>

        {/* Right: Capacity Utilization */}
        <div className="flex flex-col gap-1 w-48 items-end capacity-target">
             <div className="flex justify-between items-baseline w-full text-right">
                <div className="text-[10px] text-blue-500 uppercase font-bold tracking-widest">Weight Allowance</div>
                <div className="text-[10px] text-white font-mono">{metrics.totalWeight.toLocaleString()} / {userProfile.weightAllowance.toLocaleString()}</div>
            </div>
            <div className="w-full h-2 bg-gray-800 rounded-full overflow-hidden border border-gray-700">
                <div 
                    className={`h-full transition-all duration-1000 ${capacityUsedPercent > 90 ? 'bg-red-500' : 'bg-blue-500'}`} 
                    style={{ width: `${capacityUsedPercent}%` }} 
                />
