      // Milestone Check: Every 5th item
      if (items.length % 5 === 0) {
          setMilestone("High Value Asset");
          setTimeout(() => setMilestone(null), 4000);
      }

      const timer = setTimeout(() => setLatestItem(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [items, detectedItem]);

