import React, { useEffect, useRef, useState } from 'react';
import { InventoryItem, WasteMetrics, UserProfile } from './types';
import { useGeminiLive } from './hooks/useGeminiLive';
import { InventoryOverlay } from './components/InventoryOverlay';
import { IntroScreen } from './components/IntroScreen';
import { OnboardingTour } from './components/OnboardingTour';
import { Dashboard } from './components/Dashboard';

type ViewState = 'INTRO' | 'DASHBOARD' | 'SCANNER';

export default function App() {
  const videoRef = useRef<HTMLVideoElement>(null);

  // App View State
  const [view, setView] = useState<ViewState>('INTRO');
  const [showTour, setShowTour] = useState(false);

  // User Profile State
  const [userProfile, setUserProfile] = useState<UserProfile>({
      rank: 'E-1',
      moveType: 'PCS',
      weightAllowance: 4000
  });

  // Persistent State
  const [inventory, setInventory] = useState<InventoryItem[]>(() => {
    const saved = localStorage.getItem('moveguru_inventory');
    return saved ? JSON.parse(saved) : [];
  });

  // Ephemeral State for Visual Targeting
  const [detectedItem, setDetectedItem] = useState<InventoryItem | null>(null);

  // Save on Change
  useEffect(() => {
    localStorage.setItem('moveguru_inventory', JSON.stringify(inventory));
  }, [inventory]);

  // Derived Metrics
  const metrics: WasteMetrics = {
    totalWeight: inventory.reduce((acc, item) => acc + item.weight, 0),
    totalCarbonSaved: inventory.reduce((acc, item) => acc + item.carbonSaved, 0),
    totalTariffCredit: inventory.reduce((acc, item) => acc + item.tariffCredit, 0),
    inventoryCount: inventory.length,
    divertedWeight: inventory.reduce((acc, item) => item.status !== 'KEEP' ? acc + item.weight : acc, 0)
  };

  const handleLogin = (profile: UserProfile) => {
      setUserProfile(profile);
      setView('DASHBOARD');
      // Show tour on first login session (simplified logic)
      setShowTour(true);
  };

  const handleItemLogged = (item: InventoryItem) => {
    setInventory(prev => [...prev, item]);
  };

  const handleItemDetected = (item: InventoryItem) => {
    setDetectedItem(item);
  };

  const { isStreaming, isConnected, volume, transcript, startStream, stopStream } = useGeminiLive({
    videoRef,
    onItemLogged: handleItemLogged,
    onDetect: handleItemDetected
  });

  // Setup Video Stream
  useEffect(() => {
    let stream: MediaStream | null = null;

    async function setupCamera() {
      if (view === 'SCANNER' && videoRef.current) {
        try {
          stream = await navigator.mediaDevices.getUserMedia({ 
            video: { 
              facingMode: 'environment',
              width: { ideal: 1280 },
              height: { ideal: 720 }
            } 
          });
          videoRef.current.srcObject = stream;
        } catch (err) {
          console.error("Camera access denied", err);
        }
      }
    }

    if (view === 'SCANNER') {
      setupCamera();
    } else {
        if (videoRef.current && videoRef.current.srcObject) {
            const tracks = (videoRef.current.srcObject as MediaStream).getTracks();
            tracks.forEach(track => track.stop());
            videoRef.current.srcObject = null;
        }
    }

    return () => {
        if (stream) {
            stream.getTracks().forEach(t => t.stop());
        }
    };
  }, [view]);

  // Handlers
  const toggleStream = () => {
    if (isStreaming) {
      stopStream();
    } else {
      startStream();
    }
  };

  const exitScanner = () => {
    stopStream();
    setView('DASHBOARD');
  };

  return (
    <div className="relative w-screen h-screen bg-black overflow-hidden font-sans">

      {view === 'INTRO' && (
        <IntroScreen onLogin={handleLogin} />
      )}

      {view === 'DASHBOARD' && (
        <Dashboard 
          inventory={inventory}
          badges={[]} // Badges deprecated in Pro mode
          metrics={metrics}
          onDeploy={() => setView('SCANNER')}
          onLogout={() => setView('INTRO')}
        />
      )}

      {view === 'SCANNER' && (
        <>
            {/* 1. Camera View */}
            <video 
                ref={videoRef}
                autoPlay 
                playsInline 
                muted 
                className="absolute inset-0 w-full h-full object-cover opacity-80"
            />

            {/* 2. Grid Overlay */}
            <div className="absolute inset-0 pointer-events-none" style={{
                backgroundImage: 'linear-gradient(rgba(0, 255, 0, 0.03) 1px, transparent 1px), linear-gradient(90deg, rgba(0, 255, 0, 0.03) 1px, transparent 1px)',
                backgroundSize: '40px 40px'
            }} />

            {/* 3. Vignette */}
            <div className="absolute inset-0 pointer-events-none bg-[radial-gradient(circle_at_center,transparent_0%,rgba(0,0,0,0.6)_100%)]" />

            {/* 4. UI Layer */}
            <InventoryOverlay 
                items={inventory}
                detectedItem={detectedItem}
                metrics={metrics}
                userProfile={userProfile}
                isStreaming={isStreaming}
                isConnected={isConnected}
                volume={volume}
                transcript={transcript}
                onToggleStream={toggleStream}
                onExit={exitScanner}
            />

            {/* 5. Onboarding Tour (Overlay on top of Scanner) */}
            {showTour && (
                <OnboardingTour onClose={() => setShowTour(false)} />
            )}
        </>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { UserProfile } from '../types';

interface IntroScreenProps {
  onLogin: (profile: UserProfile) => void;
}

const RANKS = [
  { label: 'E-1 to E-4', allowance: 4000 },
  { label: 'E-5', allowance: 7000 },
  { label: 'E-6', allowance: 8000 },
  { label: 'E-7', allowance: 10000 },
  { label: 'E-8', allowance: 12000 },
  { label: 'E-9', allowance: 14000 },
  { label: 'O-1 to O-3', allowance: 12000 },
  { label: 'O-4', allowance: 14000 },
  { label: 'O-5', allowance: 16000 },
  { label: 'O-6', allowance: 18000 },
];

export const IntroScreen: React.FC<IntroScreenProps> = ({ onLogin }) => {
  const [step, setStep] = useState<number>(0);
  const [profile, setProfile] = useState<UserProfile>({
    rank: 'E-5',
    moveType: 'PCS',
    weightAllowance: 7000
  });

  const handleRankChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const selected = RANKS.find(r => r.label === e.target.value);
    setProfile(prev => ({
      ...prev,
      rank: e.target.value,
      weightAllowance: selected ? selected.allowance : 7000
    }));
  };

  const nextStep = () => setStep(prev => prev + 1);

  const requestPermissions = async () => {
    try {
      await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      nextStep(); // Go to Profile after permissions
    } catch (err) {
      alert("Microphone and Camera permissions are required for the Asset Conversion Engine.");
    }
  };

  const handleComplete = () => {
    onLogin(profile);
  };

  return (
    <div className="absolute inset-0 bg-black flex flex-col items-center justify-center p-6 z-50 overflow-hidden font-sans">

      {/* Professional Grid Background */}
      <div className="absolute inset-0 pointer-events-none" 
           style={{
             backgroundImage: 'linear-gradient(rgba(16, 185, 129, 0.05) 1px, transparent 1px), linear-gradient(90deg, rgba(16, 185, 129, 0.05) 1px, transparent 1px)',
             backgroundSize: '40px 40px'
           }} 
      />

      {/* Step 0: Splash */}
      {step === 0 && (
        <div className="z-10 text-center animate-fade-in-up">
          <div className="text-green-500 text-xs font-mono mb-4 tracking-[0.3em] uppercase">Department of Defense</div>
          <h1 className="text-6xl font-black text-white mb-2 tracking-tighter">MOVE<span className="text-green-600">GURU</span></h1>
          <p className="text-gray-400 text-sm mb-12 uppercase tracking-widest">Asset Transparency & Compliance Engine</p>

          <button 
            onClick={nextStep}
            className="px-8 py-3 bg-white text-black font-bold uppercase tracking-wider rounded hover:bg-gray-200 transition-colors"
          >
            Initialize System
          </button>
        </div>
      )}

      {/* Step 1: System Authorization (Permissions) */}
      {step === 1 && (
        <div className="z-10 w-full max-w-md bg-gray-900/90 backdrop-blur-md border border-gray-700 p-8 rounded-lg shadow-2xl animate-fade-in-up">
           <h2 className="text-xl font-bold text-white mb-6 uppercase border-b border-gray-700 pb-2">System Authorization</h2>

           <div className="space-y-4 mb-8">
             <div className="flex items-center gap-4 p-4 bg-black/50 rounded border border-gray-800">
               <div className="w-10 h-10 rounded-full bg-gray-800 flex items-center justify-center text-green-500">
                 <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
               </div>
               <div>
                 <div className="text-sm font-bold text-white">Visual Optical Sensor</div>
                 <div className="text-xs text-gray-500">Required for Asset Identification</div>
               </div>
             </div>

             <div className="flex items-center gap-4 p-4 bg-black/50 rounded border border-gray-800">
               <div className="w-10 h-10 rounded-full bg-gray-800 flex items-center justify-center text-green-500">
                 <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
               </div>
               <div>
                 <div className="text-sm font-bold text-white">Audio Input Array</div>
                 <div className="text-xs text-gray-500">Required for Officer Interrogation</div>
               </div>
             </div>
           </div>

           <button 
              onClick={requestPermissions}
              className="w-full py-4 bg-green-600 hover:bg-green-500 text-black font-bold uppercase tracking-wider rounded transition-colors shadow-[0_0_20px_rgba(22,163,74,0.3)]"
            >
              Authorize Access
            </button>
        </div>
      )}

      {/* Step 2: Profile Configuration */}
      {step === 2 && (
        <div className="z-10 w-full max-w-md bg-gray-900/90 backdrop-blur-md border border-gray-700 p-8 rounded-lg shadow-2xl animate-fade-in-up">
          <h2 className="text-xl font-bold text-white mb-6 uppercase border-b border-gray-700 pb-2">Profile Configuration</h2>

          <div className="space-y-6">
            <div>
              <label className="block text-[10px] text-green-500 uppercase tracking-widest mb-2">Service Rank / Grade</label>
              <select 
                value={profile.rank}
                onChange={handleRankChange}
                className="w-full bg-black border border-gray-700 text-white p-3 rounded focus:border-green-500 focus:outline-none transition-colors"
              >
                {RANKS.map(r => (
                  <option key={r.label} value={r.label}>{r.label} (Max {r.allowance.toLocaleString()} lbs)</option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-[10px] text-green-500 uppercase tracking-widest mb-2">Operation Type</label>
              <div className="grid grid-cols-3 gap-2">
                {['PCS', 'RETIREMENT', 'SEPARATION'].map((type) => (
                  <button
                    key={type}
                    onClick={() => setProfile(prev => ({ ...prev, moveType: type as any }))}
                    className={`text-[10px] font-bold py-3 rounded border transition-all ${profile.moveType === type ? 'bg-green-600 border-green-500 text-black' : 'bg-black border-gray-700 text-gray-400 hover:border-gray-500'}`}
                  >
                    {type}
                  </button>
                ))}
              </div>
            </div>

            <button 
              onClick={handleComplete}
              className="w-full py-4 mt-4 bg-green-600 hover:bg-green-500 text-black font-bold uppercase tracking-wider rounded transition-colors"
            >
              Confirm & Launch
            </button>
          </div>
        </div>
      )}

      <div className="absolute bottom-6 text-[10px] text-gray-600 font-mono">
        UNCLASSIFIED // FOUO // V3.0-PRO
      </div>

      <style>{`
        @keyframes fade-in-up {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-in-up {
            animation: fade-in-up 0.5s ease-out forwards;
        }
      `}</style>
    </div>
  );
};

