// src/services/TariffLogic.ts

/**
 * GSA 500A-2025 TARIFF ENGINE
 * Source: GSA Domestic 500A-2025 Tariff, Appendix A & B
 * * CORE FORMULAS:
 * 1. Linehaul (LH) = (BaseLinehaul + OriginFactor + DestFactor + Shorthaul) * LinehaulDiscount
 * 2. SIT (Storage) = (Rate * WeightCWT) * SITDiscount
 * 3. Service Charges = (OriginService + DestService) * LinehaulDiscount
 */

// --- TYPES & INTERFACES ---

export interface ShipmentParams {
  weightLbs: number;
  miles: number;
  originZip: string;
  destZip: string;
  isSITRequired: boolean;
  sitDays?: number;
}

export interface TariffCost {
  linehaul: number;
  originService: number;
  destService: number;
  packing: number;
  sit: number;
  totalGovCost: number;
  potentialSavings: number; // The "Credit" value if diverted
}

// --- GSA 500A DATA TABLES (Simulated for Prototype) ---
// In a production app, these would be queried from the Appendix B Excel DB.

// Schedule 3 is a common baseline for many metro areas.
const BASE_RATES = {
  // Section 3: Base Linehaul (Approximate from GSA 500A tables)
  // Key: Mileage Bracket, Value: Cost per CWT (Hundredweight)
  LINEHAUL_TABLE: [
    { miles: 500, rate: 45.50 },
    { miles: 1000, rate: 85.20 },
    { miles: 1500, rate: 115.75 },
    { miles: 3000, rate: 195.00 },
  ],

  // Item 135A/B: Service Charges (Per CWT)
  // Vary by "Service Area" (1-4). Schedule 3 is used here as a median.
  ORIGIN_DEST_SERVICE: 8.50, 

  // Item 185A: SIT First Day (Per CWT)
  SIT_FIRST_DAY: 21.36, // Schedule 3

  // Item 185B: SIT Additional Days (Per CWT per Day)
  SIT_ADD_DAY: 0.90,

  // Item 210A: SIT Pickup/Delivery (Flat rates based on weight brackets)
  // Schedule 3 Example: 8,000 lbs = ~$4,840
  SIT_PD_FACTOR: 56.94, // Derived Rate per CWT

  // Item 105: Full Packing (Per CWT)
  FULL_PACK: 79.73, // Schedule 2 Baseline
};

// Standard Discounts (LDF/SDF) - These fluctuate by carrier/season.
// 55% Discount = 0.45 Factor (1.00 - 0.55)
const LINEHAUL_DISCOUNT_FACTOR = 0.45; 
const SIT_DISCOUNT_FACTOR = 0.53; 

// --- CALCULATION ENGINE ---

export class TariffEngine {

  /**
   * Calculates the estimated Linehaul Charge (Transportation).
   * Formula: Base Linehaul * Discount Factor
   * (Simplification: OLF/DLF are merged into base for this prototype)
   */
  private calculateLinehaul(cwt: number, miles: number): number {
    // Find closest mileage bracket
    const bracket = BASE_RATES.LINEHAUL_TABLE.find(b => miles <= b.miles) 
                 || BASE_RATES.LINEHAUL_TABLE[BASE_RATES.LINEHAUL_TABLE.length - 1];

    const baseCharge = bracket.rate * cwt;
    return baseCharge * LINEHAUL_DISCOUNT_FACTOR;
  }

  /**
   * Calculates Origin & Destination Service Charges (Item 135A/B).
   * Formula: (Rate * CWT) * LDF
   */
  private calculateServiceCharges(cwt: number): { origin: number, dest: number } {
    const charge = (BASE_RATES.ORIGIN_DEST_SERVICE * cwt) * LINEHAUL_DISCOUNT_FACTOR;
    return { origin: charge, dest: charge };
  }

  /**
   * Calculates Storage-in-Transit (SIT) Costs (Item 185A/B + 210A).
   * This is the massive cost driver the DoD wants to avoid.
   */
  private calculateSIT(cwt: number, days: number): number {
    // 185A: First Day
    const firstDay = (BASE_RATES.SIT_FIRST_DAY * cwt) * SIT_DISCOUNT_FACTOR;

    // 185B: Additional Days
    const addDays = (BASE_RATES.SIT_ADD_DAY * cwt * (days - 1)) * SIT_DISCOUNT_FACTOR;

    // 210A: Pickup/Delivery to Warehouse
    const pickupDel = (BASE_RATES.SIT_PD_FACTOR * cwt) * SIT_DISCOUNT_FACTOR;

    return firstDay + addDays + pickupDel;
  }

  /**
   * Calculates Packing Costs (Item 105).
   * Formula: (Pack Rate * CWT) * LDF
   */
  private calculatePacking(cwt: number): number {
    return (BASE_RATES.FULL_PACK * cwt) * LINEHAUL_DISCOUNT_FACTOR;
  }

  /**
   * MASTER CALCULATOR
   * Returns the full cost profile for an item or shipment.
   */
  public analyzeItemSavings(weightLbs: number, isDiverted: boolean): TariffCost {
    const cwt = weightLbs / 100;
    const avgMiles = 1000; // Default scenario if unknown
    const avgSitDays = 30; // Standard SIT buffer

    const lh = this.calculateLinehaul(cwt, avgMiles);
    const services = this.calculateServiceCharges(cwt);
    const pack = this.calculatePacking(cwt);
    const sit = this.calculateSIT(cwt, avgSitDays);

    const totalCost = lh + services.origin + services.dest + pack + sit;

    // If diverted, we save:
    // 1. 100% of SIT (Item 185/210)
    // 2. 100% of Packing (Item 105)
    // 3. 100% of Linehaul/Services (Item 135)
    // Basically, the entire cost is avoided.
    const savings = isDiverted ? totalCost : 0;

    return {
      linehaul: Number(lh.toFixed(2)),
      originService: Number(services.origin.toFixed(2)),
      destService: Number(services.dest.toFixed(2)),
      packing: Number(pack.toFixed(2)),
      sit: Number(sit.toFixed(2)),
      totalGovCost: Number(totalCost.toFixed(2)),
      potentialSavings: Number(savings.toFixed(2))
    };
  }
}

export const tariffEngine = new TariffEngine();

// --- FURNITURE DATA (JTR Table of Measurements) ---
// Used for "Blind" estimation when we only see the item.
export const JTR_FURNITURE_DATA: Record<string, { cuFt: number, lbs: number }> = {
  // Living Room
  'Sofa (3-Seat)': { cuFt: 50, lbs: 350 }, // 7lbs density
  'Sofa (Sleeper)': { cuFt: 60, lbs: 420 }, // Heavier density
  'Chair (Upholstered)': { cuFt: 25, lbs: 175 },
  'Entertainment Center': { cuFt: 40, lbs: 280 },

  // Bedroom
  'Dresser (Double)': { cuFt: 50, lbs: 350 },
  'Dresser (Single)': { cuFt: 30, lbs: 210 },
  'Bed (King)': { cuFt: 70, lbs: 490 }, // Headboard/Footboard/Rails
  'Wardrobe': { cuFt: 45, lbs: 315 },

  // Dining
  'Table (Extension)': { cuFt: 35, lbs: 245 },
  'Chair (Dining)': { cuFt: 5, lbs: 35 },
  'Buffet/Sideboard': { cuFt: 30, lbs: 210 },
};

