      originService: Number(services.origin.toFixed(2)),
      destService: Number(services.dest.toFixed(2)),
      packing: Number(pack.toFixed(2)),
      sit: Number(sit.toFixed(2)),
      totalGovCost: Number(totalCost.toFixed(2)),
      potentialSavings: Number(savings.toFixed(2))
    };
  }
}

export const tariffEngine = new TariffEngine();

// --- FURNITURE DATA (JTR Table of Measurements) ---
// Used for "Blind" estimation when we only see the item.
